import { carbonPage, bindCarbonDashboard } from './carbon_dashboard.js?v=carbon-solar-27';
import { mountBuildingPreview } from './building_preview.js';
import { mountSpatialTwin, FACILITIES } from './spatial_twin.js?v=renewable-workspace-26';
import { floorOptions, floorZones, floorIssueCount, facilityAlerts, syncAlertState, FLOOR_COUNTS } from './floor_conditions.js?v=alert-approval-16';
import { simulatorPage, mountInstallation, installation, simulatorUI, syncSimulatorForm, bindSimulator, simulatorDesign, scenarioPayload } from './renewable_simulator.js?v=carbon-solar-27';

const PAGES = [
  ['overview', 'Overview'], ['monitoring', 'Monitoring'], ['carbon', 'Carbon'],
  ['simulator', 'Renewable Simulator'], ['copilot', 'AI Copilot'],
];
const app = document.getElementById('app');
const dialog = document.getElementById('confirm-dialog');
let previewInstance=null;
let buildingView=null;
let installationView=null;
let townshipReturn=null;
let townshipView=null;
let requestSequence=0;
let storedPreferences={};
try { storedPreferences=JSON.parse(localStorage.getItem('energios-view')||'{}'); } catch {}
const state = { assets: [], assetId: null, period: 'day', data: null, page: 'overview',
  loading: true, error: null, floor: 'whole', room: 'Overview', chatOpen: false,
  chat: [], chatBusy: false, scenarioTech: 'pv_battery', scenarioDraft: null,
  preview: null, previewError: null, toast: '', chartMetric:'energy', scenarioName:'PV and battery', calculating:false, menuOpen:false,
  spatialFacility:null, spatialNight:false, township:null, energyLayer:'hvac', geminiStatus:'checking' };
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = (value, digits = 0) => value == null || !Number.isFinite(Number(value)) ? 'Not calculated' : new Intl.NumberFormat('en-MY', {maximumFractionDigits: digits, minimumFractionDigits: digits}).format(Number(value));
const unit = (value, suffix, digits = 0) => value == null ? 'Not calculated' : `${num(value, digits)} ${suffix}`;
const money = value => value == null ? 'Not calculated' : `RM ${num(value, 2)}`;
const sourceName = asset => asset?.facility_id ? asset.name : asset?.source_asset_id?.replace(/^Hog_/, '').replaceAll('_', ' ') || 'Building';
const dateOnly = value => value ? new Date(`${value.slice(0,10)}T12:00:00Z`).toLocaleDateString('en-MY',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}) : '—';
const sourceHour = (utc, zone) => new Intl.DateTimeFormat('sv-SE', {timeZone:zone, year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(utc)).replace(' ','T');
const route = () => { const value = location.hash.replace('#','').toLowerCase(); return PAGES.some(([id])=>id===value) ? value : 'overview'; };
async function q(path,options={}){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),20000);try{const response=await fetch(`/api/workbench${path}`,{...options,signal:controller.signal,headers:{Accept:'application/json',...(options.body?{'Content-Type':'application/json'}:{})}});if(!response.ok){let message=`Request failed (${response.status})`;try{const payload=await response.json();message=typeof payload.detail==='string'?payload.detail:Array.isArray(payload.detail)?payload.detail.map(item=>item.msg).join('; '):message}catch{}throw Error(message)}return await response.json()}catch(error){if(error.name==='AbortError')throw Error('The local API took too long. Please retry.');throw error}finally{clearTimeout(timeout)}}
const post = (path, body) => q(path,{method:'POST',body:JSON.stringify(body)});
async function checkGeminiStatus(){try{const status=await q('/copilot/status');state.geminiStatus=status.available?'available':'unavailable'}catch{state.geminiStatus='unavailable'}if(state.chatOpen||state.page==='copilot')render()}
const stamp = () => `${dateOnly(state.data?.observed_window?.from)}–${dateOnly(state.data?.observed_window?.to)}`;
const actionButton = (id,label,cls='primary',extra='') => `<button type="button" class="${cls}" data-action="${id}" ${extra}>${label}</button>`;
function rememberView(){try{localStorage.setItem('energios-view',JSON.stringify({assetId:state.assetId,period:state.period}))}catch{}}
function selectAsset(id){state.calculating=false;simulatorUI.saved=null;simulatorUI.editing=null;simulatorUI.compare=[];state.assetId=id;state.spatialFacility=state.assets.find(a=>a.id===id)?.facility_id||null;state.preview=null;state.scenarioDraft=null;state.floor='whole';state.room='Overview';buildingView=null;installationView=null;state.chat=[];rememberView();return refresh();}
async function openFacility(id,view=null,focusAlert=false){const asset=state.assets.find(a=>a.facility_id===id);if(asset){townshipView=view;await selectAsset(asset.id);window.scrollTo({top:0,behavior:'instant'});if(focusAlert&&state.spatialFacility===id){const alert=facilityAlerts(id)[0];if(alert){selectFloor(alert.floor);selectFloorRoom(alert.id);document.querySelector('.floor-inspector')?.scrollIntoView({block:'nearest',behavior:'smooth'});}}}}
async function refresh(){
  if(!state.assetId)return;
  const sequence=++requestSequence;
  state.loading=true;state.error=null;render();
  try { const [data,township]=await Promise.all([q(`/state?asset_id=${encodeURIComponent(state.assetId)}&period=${state.period}`),q(`/township?period=${state.period}`)]);if(sequence!==requestSequence)return;state.data=data;state.township=township;syncAlertState(township.items);state.scenarioDraft={...data.config}; }
  catch(error){if(sequence!==requestSequence)return;state.error=error.message;state.data=null;}
  finally {if(sequence===requestSequence){state.loading=false;render();}}
}
async function init(){
  state.page=route();
  try { const result=await q('/assets');state.assets=[...(result.facilities||[]),...(result.items||[])];if(!state.assets.length)throw Error('No buildings are available.');const townshipAssets=state.assets.filter(asset=>asset.facility_id);state.assetId=townshipAssets.find(asset=>asset.id===storedPreferences.assetId)?.id||townshipAssets[0]?.id||state.assets[0].id;state.spatialFacility=state.page==='overview'?null:state.assets.find(a=>a.id===state.assetId)?.facility_id||null;state.period=['day','week'].includes(storedPreferences.period)?storedPreferences.period:'day';await refresh();await checkGeminiStatus(); }
  catch(error){state.loading=false;state.error=error.message;render();}
}
function header(){
  return `<header class="topbar"><button class="mobile-menu" data-action="toggle-menu" aria-label="Navigation menu" aria-expanded="${state.menuOpen}">☰</button><a class="logo" href="#overview" aria-label="Nexora overview"><img class="logo-image" src="/assets/nexora-logo.png" alt="Nexora — Powering tomorrow, intelligently"></a>
  <nav class="nav ${state.menuOpen?'open':''}" aria-label="Main navigation">${PAGES.filter(([id])=>id!=='copilot').map(([id,label])=>`<a href="#${id}" class="${state.page===id?'active':''}" ${state.page===id?'aria-current="page"':''}>${({overview:'Overview',monitoring:'Real-Time & Forecast',carbon:'Carbon Dashboard'})[id]||label}</a>`).join('')}</nav>
  </header>`;
}
function filters(){const all=state.page==='overview'&&!state.spatialFacility;return `<div class="filters">${all?'<span class="badge gray">All 6 facilities</span>':`<div class="building-filter"><label class="select-wrap"><span class="sr-only">Township building</span><select id="building-select" aria-label="Choose a township building">${state.assets.filter(asset=>asset.facility_id).map(asset=>`<option value="${asset.id}" ${asset.id===state.assetId?'selected':''}>${esc(sourceName(asset))}</option>`).join('')}</select></label>${state.page==='monitoring'?'<small class="building-filter-hint">Choose one of the six township buildings to view its estimated profile.</small>':''}</div>`}<label class="select-wrap"><select id="period-select" aria-label="History window"><option value="day" ${state.period==='day'?'selected':''}>24-hour view</option><option value="week" ${state.period==='week'?'selected':''}>7-day view</option></select></label></div>`}
function heading(title,subtitle,controls=true){return `<div class="page-head"><div><h1>${title}</h1><p>${subtitle}</p></div>${controls?filters():''}</div>`}
function sourceStrip(){const d=state.data;return `<div class="source-strip"><span><i class="dot"></i><strong>${d.asset.facility_id?'Township estimate · benchmark-derived':'Public benchmark · BDG2 v1.0'}</strong> · ${stamp()} · ${esc(d.asset.timezone)}</span><span>${d.asset.facility_id?'Illustrative energy, cost & carbon':'Historical readings · Estimated costs & simulations'}</span></div>`}
function kpi(label,value,sub,kind='blue',icon='↗',series=null){const values=(series||state.data?.observed||[]).slice(-24).map(r=>r.consumption_kwh);const min=Math.min(...values),max=Math.max(...values),points=values.map((v,i)=>`${i*72/Math.max(values.length-1,1)},${26-(v-min)*20/Math.max(max-min,1)}`).join(' ');return `<div class="card kpi ${kind}"><span class="label">${label}</span><span class="kpi-icon">${icon}</span><div class="value">${value}</div><div class="sub">${sub}</div><svg class="sparkline" viewBox="0 0 74 30" aria-hidden="true"><polyline points="${points}" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></div>`}
function chart(valuesA,valuesB,labels,{colors=['#e96b12','#f2a13a'],mode='split',height=205,labelsB=null,chartUnit='kWh',dashed=true,seriesATitle=null,seriesBTitle='Forecast',ariaLabel=null}={}){
  const all=[...valuesA,...valuesB].filter(Number.isFinite),max=Math.max(...all,1)*1.15,min=0,w=700,h=height,left=34,right=12,top=12,bottom=29,innerW=w-left-right,innerH=h-top-bottom;
  const x=index=>left+index*innerW/Math.max(1,mode==='split'?valuesA.length+valuesB.length-1:Math.max(valuesA.length,valuesB.length)-1);
  const y=value=>top+(max-value)*innerH/max;
  const line=(values,start=0)=>{const pts=values.map((v,i)=>[x(i+start),y(v)]);if(!pts.length)return '';let path=`M${pts[0].join(',')}`;for(let i=0;i<pts.length-1;i++){const p0=pts[Math.max(0,i-1)],p1=pts[i],p2=pts[i+1],p3=pts[Math.min(pts.length-1,i+2)];path+=` C${p1[0]+(p2[0]-p0[0])/6},${p1[1]+(p2[1]-p0[1])/6} ${p2[0]-(p3[0]-p1[0])/6},${p2[1]-(p3[1]-p1[1])/6} ${p2[0]},${p2[1]}`;}return path;};
  const circle=(values,start,isForecast)=>values.map((v,i)=>`<circle cx="${x(i+start).toFixed(1)}" cy="${y(v).toFixed(1)}" r="7" fill="transparent" stroke="transparent"><title>${esc(isForecast?seriesBTitle:(seriesATitle||(state.data?.asset.facility_id?'Estimated reference':'Recorded reference')))} · ${esc((isForecast&&labelsB?labelsB[i]:labels[i+start])||`Interval ${i+start+1}`)}: ${num(v,1)} ${esc(chartUnit)}</title></circle>`).join('');
  const bStart=mode==='split'?valuesA.length:0;
  const ticks=[0,.25,.5,.75,1].map(p=>`<line x1="${left}" x2="${w-right}" y1="${top+p*innerH}" y2="${top+p*innerH}"/><text class="chart-axis" x="2" y="${top+p*innerH+3}">${num(max*(1-p),0)}</text>`).join('');
  const xticks=[0,.25,.5,.75,1].map(p=>`<text class="chart-axis" x="${left+p*innerW}" y="${h-4}" text-anchor="middle">${esc(labels[Math.round(p*(labels.length-1))]?.slice(11,16)||'')}</text>`).join('');
  return `<div class="chart-holder"><svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(ariaLabel||`Recorded and forecast ${chartUnit} chart; hover a point for its date and value`)}"><path d="${line(valuesA)} L${x(valuesA.length-1)},${top+innerH} L${left},${top+innerH}Z" fill="${colors[0]}" opacity=".055"/><g class="chart-grid">${ticks}</g>${xticks}<path class="chart-line" stroke="${colors[0]}" d="${line(valuesA)}"/><path class="chart-line" stroke="${colors[1]}" ${dashed?'stroke-dasharray="5 4"':''} d="${line(valuesB,bStart)}"/>${circle(valuesA,0,false)}${circle(valuesB,bStart,true)}</svg></div>`;
}
function forecastChart(metric='energy'){const d=state.data,a=d.observed.slice(-24),b=d.forecast,factor=metric==='cost'?d.config.tariff_myr_per_kwh:metric==='carbon'?d.config.carbon_kg_per_kwh:1;if(factor==null)return '<div class="empty">The selected calculation factor is not configured.</div>';const colors=metric==='carbon'?['#ed6a0b','#f5a623']:metric==='cost'?['#c94e08','#f2a13a']:['#ed6a0b','#f5a623'];return chart(a.map(r=>r.consumption_kwh*factor),b.map(r=>r.forecast_kwh*factor),a.map(r=>r.source_local_timestamp),{mode:'overlay',labelsB:b.map(r=>sourceHour(r.timestamp,d.asset.timezone)),colors,chartUnit:metric==='cost'?'RM':metric==='carbon'?'kg CO₂e':'kWh'})}
const ENERGY_LAYERS=[['hvac','HVAC'],['grid','Grid'],['solar','Solar']];
// Illustrative daily energy inputs for the model overlay only, in kWh.
const MODEL_ENERGY_DEMO={mall:{hvac:3260,grid:5120,solar:480},hospital:{hvac:4200,grid:7900,solar:0},restaurant:{hvac:124,grid:280,solar:0},commercial:{hvac:2300,grid:4300,solar:360},residential:{hvac:1800,grid:3400,solar:540},solar:{hvac:0,grid:18,solar:4800}};
function energyLayerInfo(){const id=state.energyLayer,profile=MODEL_ENERGY_DEMO[state.spatialFacility]||MODEL_ENERGY_DEMO.commercial,period=state.period==='week'?7:1;const labels={hvac:['HVAC zone','Energy used'],grid:['Grid supply','Energy supplied'],solar:['Solar generation','Energy generated']};return `<strong>${labels[id][0]}</strong><span>${labels[id][1]}: <b>${unit(profile[id]*period*(id==='solar'?1:1-(state.data.alerts||[]).filter(a=>a.status==='settled').reduce((sum,a)=>sum+a.fraction,0)),'kWh',1)}</b></span><small>Estimated profile · ${period===7?'7 days':'24 hours'}</small>`}
function selectFloor(floor){
  if(!floorOptions(state.spatialFacility).some(f=>f.id===floor))return;
  if(floor===state.floor)return;
  state.floor=floor;state.room='Overview';
  if(previewInstance?.setFloor){previewInstance.setFloor(floor);document.querySelectorAll('[data-floor]').forEach(button=>{const active=button.dataset.floor===floor;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))});updateFloorInspector();}
  else {buildingView=previewInstance?.getView?.()||null;render();}
}
function updateFloorInspector(){const panel=document.querySelector('.floor-inspector');if(panel)panel.outerHTML=floorInspector();}
function selectFloorRoom(room){state.room=room;updateFloorInspector();}
function floorNavigator(){
  if(!state.spatialFacility||state.spatialFacility==='solar')return '';
  return `<nav class="floor-navigation" aria-label="Select building floor">${floorOptions(state.spatialFacility).map(f=>{const issues=floorIssueCount(state.spatialFacility,f.id);return `<button type="button" data-floor="${f.id}" aria-pressed="${state.floor===f.id}" class="${state.floor===f.id?'active':''}" title="${f.label}${issues?' · '+issues+' estimated alert':''}">${f.label}${issues?'<span class="floor-alert" aria-label="Floor alert">!</span>':''}</button>`}).join('')}</nav>`;
}
function floorInspector(){
  if(!state.spatialFacility)return '';
  if(state.spatialFacility==='solar')return '<div class="floor-inspector"><strong>Solar farm · Outdoor site</strong><p>No occupied floors in this model.</p></div>';
  const options=floorOptions(state.spatialFacility),zones=floorZones(state.spatialFacility,state.floor),label=options.find(f=>f.id===state.floor)?.label||'Whole building';
  if(!zones.length)return `<section class="floor-inspector"><div class="floor-inspector-head"><h3>Explore inside</h3><span class="badge gray">Estimated conditions</span></div><p>${facilityAlerts(state.spatialFacility).length?'Select a floor above or click an alert below to inspect it.':'All floor alerts are settled. Select a floor to explore.'}</p><div class="building-alert-list">${facilityAlerts(state.spatialFacility).map(a=>`<button type="button" data-alert-floor="${a.floor}" data-alert-zone="${a.id}"><span class="alert-list-symbol" aria-hidden="true">!</span><span><strong>${esc(a.floorLabel)} · ${esc(a.name)}</strong><small>${esc(a.issue)}</small></span><b>View →</b></button>`).join('')}</div><small>${FLOOR_COUNTS[state.spatialFacility]} occupied floors · Roof plant · Estimated conditions</small></section>`;
  const selected=zones.find(z=>z.id===state.room)||zones.find(z=>z.status!=='Normal')||zones[0],days=state.period==='week'?7:1,hvac=(MODEL_ENERGY_DEMO[state.spatialFacility]?.hvac||0)*days/(FLOOR_COUNTS[state.spatialFacility]+1);
  return `<section class="floor-inspector" aria-label="Floor conditions"><div class="floor-inspector-head"><h3>${esc(label)} · Room conditions</h3><span class="badge gray">Estimated</span></div><p>${state.floor==='roof'?'Roof equipment view':'Cutaway view'} · Select a zone to inspect.</p><div class="floor-zones">${zones.map(z=>`<button type="button" data-floor-zone="${z.id}" aria-pressed="${z.id===selected.id}" class="floor-zone ${z.status.toLowerCase()} ${z.id===selected.id?'selected':''}"><span class="zone-status-dot"></span><strong>${esc(z.name)}</strong><small>${z.status}${z.temperature==null?'':' · '+num(z.temperature,1)+'°C'}</small></button>`).join('')}</div><div class="floor-issue-detail ${selected.status.toLowerCase()}" role="status"><strong>${esc(selected.name)} · ${selected.status}</strong><p>${esc(selected.issue)}</p><p><strong>AI suggestion:</strong> ${esc(selected.action)}</p><div class="floor-condition-values"><span>Temperature <b>${selected.temperature==null?'Not applicable':num(selected.temperature,1)+'°C'}</b></span><span>Occupancy <b>${selected.occupancy} people</b></span><span>Allocated HVAC <b>${unit(hvac*selected.share,'kWh',1)}</b></span></div></div><details class="details"><summary>Calculation basis</summary><p>Illustrative room conditions. HVAC allocation = modeled building HVAC input ÷ (${FLOOR_COUNTS[state.spatialFacility]} floors + roof) × zone share · ${days===7?'7 days':'24 hours'}. No sensor or equipment connection. Coloured zones are conceptual and are not an architectural floor plan.</p></details></section>`;
}
function buildingScene(tall=false){
  const selected=state.floor, fill=(floor,normal,active)=>selected===floor?active:normal;
  return `${floorNavigator()}<div class="building-stage" style="${tall?'height:375px':''}">
  <div class="building-canvas" data-tall="${tall}"></div><div class="energy-layer-controls" role="group" aria-label="Building energy systems">${ENERGY_LAYERS.map(([id,label])=>`<button type="button" class="energy-layer-button ${state.energyLayer===id?'active':''}" data-energy-layer="${id}" aria-pressed="${state.energyLayer===id}"><i class="energy-layer-dot ${id}"></i>${label}</button>`).join('')}</div><div class="orbit-toolbar"><button data-camera="in" aria-label="Zoom in">⊕</button><button data-camera="out" aria-label="Zoom out">⊖</button><button data-camera="reset" aria-label="Reset camera">⟳</button><button data-camera="rotate" aria-label="Toggle building rotation">↻</button></div>
  <svg class="building-svg" viewBox="0 0 480 270" role="img" aria-label="Illustrative interactive building model with selectable floors" style="${tall?'height:340px;width:min(96%,540px)':''}">
    <defs><linearGradient id="side" x1="0" x2="1" y1="0" y2="1"><stop stop-color="#f9fcfd"/><stop offset="1" stop-color="#d4e2eb"/></linearGradient><filter id="shadow"><feGaussianBlur stdDeviation="6"/></filter></defs>
    <ellipse cx="251" cy="237" rx="155" ry="20" fill="#9eb4c0" opacity=".18" filter="url(#shadow)"/>
    <path d="M108 152 L232 99 L383 147 L261 203Z" fill="#d9e6ea" opacity=".55"/>
    <g data-floor="ground"><path d="M124 165 L252 210 L252 232 L124 186Z" fill="${fill('ground','#dce8ef','#b5d9e8')}" stroke="#c2d5df"/><path d="M252 210 L365 166 L365 187 L252 232Z" fill="${fill('ground','#d4e2ea','#9fcddd')}" stroke="#c2d5df"/></g>
    <g data-floor="level_1"><path d="M124 127 L252 171 L252 210 L124 165Z" fill="${fill('level_1','url(#side)','#bcdeea')}" stroke="#c9dce5"/><path d="M252 171 L365 128 L365 166 L252 210Z" fill="${fill('level_1','#e8f0f4','#a7d2e2')}" stroke="#c9dce5"/><path d="M124 126 L252 171 L365 128" fill="none" stroke="#bad3de"/></g>
    <g data-floor="roof"><path d="M124 126 L238 82 L365 127 L252 171Z" fill="${fill('roof','#f3f8f9','#d8f5ee')}" stroke="#bbd0d8" stroke-width="2"/><path d="M124 126 L252 171 L365 127" fill="none" stroke="#a8c1cd"/></g>
    <g fill="#0d5ea8" stroke="#3a83bc" stroke-width="1" pointer-events="none"><path d="M183 111 l27 -10 22 8 -27 10Z M217 99 l27 -10 22 8 -27 10Z M251 88 l27 -10 22 8 -27 10Z M209 121 l27 -10 22 8 -27 10Z M243 109 l27 -10 22 8 -27 10Z M277 98 l27 -10 22 8 -27 10Z M235 131 l27 -10 22 8 -27 10Z M269 120 l27 -10 22 8 -27 10Z"/></g>
    <g stroke="#b4cbd7" stroke-width="2" pointer-events="none"><path d="M136 145 l104 35 M136 155 l104 35 M136 165 l104 35 M264 181 l89 -34 M264 194 l89 -34 M264 207 l89 -34"/></g>
    <g fill="#eff7fa" stroke="#c0d6df" pointer-events="none"><rect x="87" y="186" width="23" height="17" rx="3"/><rect x="376" y="166" width="20" height="19" rx="3"/><rect x="386" y="203" width="14" height="11" rx="2"/></g>
    <g fill="#23bd9c" pointer-events="none"><circle cx="99" cy="184" r="3"/><circle cx="386" cy="164" r="3"/><circle cx="395" cy="202" r="3"/></g>
    <text x="247" y="247" text-anchor="middle" fill="#7292a1" font-size="10">${esc(sourceName(state.data.asset))} · illustrative model</text>
  </svg><div class="energy-layer-info" role="status" aria-live="polite">${energyLayerInfo()}</div></div>${floorInspector()}`;
}
function overviewKpis(data,total=false){const m=data.metrics,period=state.period==='day'?'24 hours':'7 days';return `<section class="grid kpis overview-kpis" aria-label="${total?'Township totals':esc(sourceName(data.asset))+' metrics'}" data-kpi-scope="${total?'township':esc(data.asset.facility_id||data.asset.id)}">${kpi(total?'Total Energy Consumption':'Energy Consumption',unit(m.observed_energy_kwh,'kWh'),`Past · ${period}`,'blue','ϟ',data.observed)}${kpi(total?'Total Electricity Cost':'Electricity Cost',money(m.observed_cost_estimate_myr),'Past · assumed tariff','teal','▱',data.observed)}${kpi(total?'Total CO₂e Emissions':'CO₂e Emissions',unit(m.observed_carbon_estimate_kg,'kg'),'Past · assumed factor','green','♧',data.observed)}</section>`}
function township(){const d=state.township;return `${heading('Township Digital Twin','Explore the neighbourhood. Select a building to open its energy workspace.')}
  <div class="source-strip"><span><i class="dot"></i><strong>Township total · ${d.facility_count} estimated facilities</strong> · ${dateOnly(d.observed_window.from)}–${dateOnly(d.observed_window.to)} · ${esc(d.observed_window.timezone)}</span><span>Illustrative energy, cost & carbon</span></div>
  ${overviewKpis(d,true)}
  <section class="township-card card" aria-label="Township spatial digital twin">
    <div class="township-top"><div class="township-heading"><span class="township-indicator"></span><strong>Nexora Township</strong><span class="badge">Illustrative masterplan</span></div><div class="township-tools"><button class="ghost" data-camera="reset" aria-label="Reset township camera">⟲</button><button class="ghost" data-action="township-night" aria-label="${state.spatialNight?'Switch to day':'Switch to night'}">${state.spatialNight?'☀':'☾'}</button></div></div>
    <div class="township-stage ${state.spatialNight?'night':''}"><div class="township-canvas"></div><div class="township-labels"></div><div class="township-compass" aria-label="North direction">N<span>↑</span></div><div class="township-guide">Select a building to explore <span>Drag to orbit · scroll to zoom</span></div><div class="township-fallback" hidden>3D graphics could not start. Select a facility below to continue.</div></div>
  </section><div class="facility-directory" aria-label="Select a township facility">${FACILITIES.map(f=>`<button data-facility="${f.id}" style="--facility-color:${f.color}"><i></i><span>${esc(f.type)}<small>${esc(f.name)}</small></span><b>↗</b></button>`).join('')}</div>
  ${townshipAlertPanel()}
  <details class="details township-data"><summary>Township data and model basis</summary><p>The township cards sum all six facility profiles for the selected period. Each is a separate estimate using a historical BDG2 load profile and the multiplier below. Cost and carbon use each facility’s editable assumptions. These are architectural concepts, not measured sites. Solar farm consumption covers auxiliary site load; solar generation and grid energy avoided are separate.</p><div class="township-basis-list">${d.items.map(({asset:a})=>`<div class="stat-row"><span>${esc(a.name)}</span><strong>${esc(a.demo_basis.source_asset_id)} × ${num(a.demo_basis.load_multiplier,3)}</strong></div>`).join('')}</div><p>Missing cost or carbon inputs make that total unavailable. No incomplete subtotal is presented as a township total.</p></details>`}
function details(){const d=state.data;return `<details class="details"><summary>Data and calculation details</summary><p>${d.asset.facility_id?`Estimated profile: ${esc(d.asset.name)}. Input = ${esc(d.asset.demo_basis.source_asset_id)} × ${num(d.asset.demo_basis.load_multiplier,3)}. No measured facility consumption or facility-specific accuracy is available. Source history was recorded`:`Measured source: ${esc(d.data_label)}. Hourly readings were recorded`} during ${stamp()} in ${esc(d.asset.timezone)}. The 24-hour forecast is calculated from historical benchmark data. Cost and carbon use editable assumptions. Floor, room, equipment, PV and storage values are illustrative simulations; no physical control is connected.</p><p>The frozen API snapshot was fetched 14 Oct 2026. BDG2 is not Sime Darby or Elmina operational data. <a href="https://doi.org/10.5281/zenodo.3887306" target="_blank" rel="noopener">Dataset · CC BY 4.0</a> · <a href="https://doi.org/10.1038/s41597-020-00712-x" target="_blank" rel="noopener">Miller et al., Scientific Data (2020)</a>.</p></details>`}
function buildingConditions(){
  const facility=state.spatialFacility,c=state.data.config;
  const profiles={mall:[23.4,61,601,42,48],hospital:[22.6,55,530,32,42],restaurant:[24.2,64,720,48,54],commercial:[23,58,580,38,40],residential:[24,62,640,40,36],solar:[25,60,440,25,38]};
  const [baseTemperature,humidity,co2,aqi,noise]=profiles[facility]||profiles.commercial;
  const settled=(state.data.alerts||[]).filter(a=>a.status==='settled').length,temperature=settled?Math.max(c.cooling_setpoint_c,baseTemperature-settled*.15):baseTemperature;
  const occupancy=floorOptions(facility).filter(f=>!['whole','roof'].includes(f.id)).flatMap(f=>floorZones(facility,f.id)).reduce((sum,z)=>sum+z.occupancy,0);
  const item=(icon,label,value,tone='blue')=>`<div class="condition-tile"><span class="condition-icon ${tone}" aria-hidden="true">${icon}</span><div><span class="condition-label">${label}</span><strong>${value}</strong></div></div>`;
  return `<section class="building-conditions" aria-label="Whole building indoor and outdoor conditions"><section class="card conditions-card"><div class="conditions-heading"><h2>Indoor</h2><span class="condition-scope">Whole building</span></div><div class="condition-grid">${item('♨','Temperature',`${temperature.toFixed(1)} °C`)}${item('◉','Humidity',`${humidity} %`)}${item('♙','Occupancy',`${occupancy} people`)}${item('≋','Air quality',`${co2} ppm CO₂`)}${item('⌁','Air quality index',`Good · ${aqi}`,'green')}${item('♪','Noise level',`${noise} dB`)}${item('☀','Lights',facility==='solar'?'Off':'On','amber')}${item('❄','HVAC',facility==='solar'?'Standby':'Cooling')}</div><div class="conditions-foot">Cooling setpoint <strong>${num(c.cooling_setpoint_c,1)} °C</strong></div></section><section class="card conditions-card"><div class="conditions-heading"><h2>Outdoor</h2><span class="condition-scope">Building site</span></div><div class="condition-grid">${item('♨','Temperature','29.3 °C','gray')}${item('☁','Weather','Partly cloudy','gray')}${item('◉','Humidity','77 %','gray')}${item('☀','Solar irradiance','673 W/m²','amber')}${item('≋','Wind','11 km/h SW','gray')}${item('☂','Rainfall','0 mm','gray')}</div><div class="conditions-foot"><span>Sunrise <strong>7:04 AM</strong></span><span>Sunset <strong>7:26 PM</strong></span></div></section><details class="conditions-basis"><summary>Condition details</summary><p>Estimated whole-building conditions and assumed site weather. Occupancy sums the floor profiles; cooling setpoint uses the shared building configuration. These values are a planning snapshot, independent of the energy chart’s historical period. No environmental sensors or weather service are connected.</p></details></section>`;
}
function overview(){if(!state.spatialFacility)return township();const facility=FACILITIES.find(f=>f.id===state.spatialFacility),d=state.data;return `<div class="facility-breadcrumb"><button class="township-return" data-action="township-back">← Back to township</button><span>/</span><span>${esc(facility.type)}</span></div>${heading(facility.name,`Estimated ${facility.type.toLowerCase()} · Individual building results`)}${sourceStrip()}
  ${overviewKpis(d)}
  <div class="overview-workspace facility-enter"><section class="card card-pad building-card"><div class="card-head"><h2>Facility Digital Twin</h2><span class="badge">${esc(facility.type)}</span></div>${buildingScene()}<div class="building-foot"><button class="township-return" data-action="township-back">← Back to township</button><span>Drag to rotate · scroll to zoom</span></div><div class="model-legend"><span><i></i>Architectural concept</span><span><i style="background:#d6a143"></i>Benchmark comparison</span></div></section>
  <div class="overview-right" role="region" aria-label="Energy trend and action cards" tabindex="0">${buildingConditions()}${recommendationPanel()}${approvedAlertImpact()}<section class="card card-pad chart-card"><div class="card-head"><h2>Energy Load Trend</h2><div class="segmented">${[['energy','Energy'],['cost','Cost'],['carbon','CO₂']].map(([id,label])=>`<button data-chart-metric="${id}" class="${state.chartMetric===id?'active':''}">${label}</button>`).join('')}</div></div><p class="note" style="margin-bottom:10px">${d.asset.facility_id?'31 Dec estimated profile · 1 Jan projected profile':'31 Dec recorded profile · 1 Jan forecast profile'} · source-local hours</p>${forecastChart(state.chartMetric)}<div class="legend"><span><i style="background:#ed6a0b"></i>${d.asset.facility_id?'Estimated profile':'Recorded day'}</span><span><i style="background:#f5a623"></i>Following forecast day</span></div>${details()}</section>
</div></div>`}
function monitoring(){
  const d=state.data,m=d.metrics,model=d.model,shift=d.shift;
  const modelMae=model.test_metrics.model.mae_kwh,baselineMae=model.test_metrics.baseline.mae_kwh,samples=model.test_metrics.model.n;
  const relativeError=baselineMae?((baselineMae-modelMae)/baselineMae)*100:null,modelBeatsBaseline=relativeError!=null&&relativeError>=0;
  const modelStatus=relativeError==null?'No comparison':modelBeatsBaseline?'Beat baseline':'Higher error';
  const referenceLabel=d.asset.facility_id?'Estimated reference':'Recorded reference';
  const optimizationValues=shift.items.map(row=>row.after_kwh),forecastValues=d.forecast.map(row=>row.forecast_kwh);
  const energyMoved=shift.items.reduce((total,row)=>total+Math.max(0,row.after_kwh-row.before_kwh),0);
  const optimizationChart=chart(forecastValues,optimizationValues,d.forecast.map(row=>sourceHour(row.timestamp,d.asset.timezone)),{
    mode:'overlay',labelsB:d.forecast.map(row=>sourceHour(row.timestamp,d.asset.timezone)),height:190,
    colors:['#ed6a0b','#5b9f50'],chartUnit:'kWh',seriesATitle:'Forecast before load shift',seriesBTitle:'Illustrative shifted forecast',ariaLabel:'Next-day forecast load compared with an illustrative shifted load profile, in hourly kWh'
  });
  const peakBefore=Math.max(...shift.items.map(row=>row.before_kwh)),peakAfter=Math.max(...shift.items.map(row=>row.after_kwh));
  return `${heading('Real-Time & Forecast','See the selected history, what the model forecasts next, and how it performed.')}${sourceStrip()}
  <div class="monitoring-kpis">${kpi(state.period==='day'?`${referenceLabel} · 24 hours`:`${referenceLabel} · 7 days`,unit(m.observed_energy_kwh,'kWh',1),'Selected historical reference','blue','ϟ')}${kpi('Estimated energy cost',money(m.observed_cost_estimate_myr),'Uses the configured flat rate','teal','RM')}${kpi('Next 24-hour forecast',unit(m.forecast_energy_kwh,'kWh',1),'Calculated from historical data','green','↗')}${kpi('Reference peak',unit(m.observed_peak_interval_average_kw,'kW',1),'Highest hourly interval in selected history','blue','⌁')}</div>
  <div class="grid split-grid monitoring-comparison monitoring-primary"><section class="card card-pad monitoring-chart-card"><div class="card-head monitoring-card-heading"><div><span class="eyebrow">Energy use</span><h2>Recent profile and next-day forecast</h2><p class="caption">Hourly energy for ${esc(sourceName(d.asset))} · ${esc(d.asset.timezone)} local time</p></div><div class="segmented" aria-label="Chart units">${[['energy','Energy'],['cost','Est. cost'],['carbon','CO₂e']].map(([id,label])=>`<button type="button" data-chart-metric="${id}" class="${state.chartMetric===id?'active':''}" aria-pressed="${state.chartMetric===id}">${label}</button>`).join('')}</div></div><p class="monitoring-chart-explain">The solid line is the selected reference day. The dashed line is the following day’s forecast.</p>${forecastChart(state.chartMetric)}<div class="legend"><span><i style="background:#ed6a0b"></i>${referenceLabel}</span><span><i style="background:#f5a623"></i>Forecast · next day</span></div><details class="monitoring-chart-details"><summary>How to read this chart</summary><p>Each point is energy used or forecast for one hour, in kWh. The selected ${state.period==='day'?'24-hour':'7-day'} period changes the reference summary above; the chart compares the most recent reference day with the next 24-hour forecast. Estimated cost and carbon views use the configured flat-rate assumptions.</p></details></section>
  <section class="card card-pad monitoring-health"><div class="card-head"><div><span class="eyebrow">Model check</span><h2>How reliable is this forecast?</h2></div><span class="badge ${modelBeatsBaseline?'monitoring-status-good':'monitoring-status-watch'}">${modelStatus}</span></div><p class="monitoring-health-summary">The model was tested on past data it had not seen during training. Lower error means a closer forecast.</p><div class="monitoring-error-comparison"><div><span>Forecast model error</span><strong>${unit(modelMae,'kWh / hour',1)}</strong></div><div><span>Simple baseline error</span><strong>${unit(baselineMae,'kWh / hour',1)}</strong></div></div><div class="forecast-score"><strong>${relativeError==null?'—':`${num(Math.abs(relativeError),1)}% ${relativeError>=0?'lower':'higher'} error`}</strong><span>Compared with the simple baseline in the same test</span></div><div class="stat-row"><span>Past test intervals</span><strong>${num(samples)}</strong></div><p class="note monitoring-model-note">Historical BDG2 benchmark test only. It does not measure accuracy for this specific facility or today. Source history ends in 2017.</p></section></div>
  <section class="card card-pad monitoring-optimization"><div class="card-head monitoring-card-heading"><div><span class="eyebrow">Planning scenario</span><h2>What if flexible load moved away from the peak?</h2><p class="caption">A modelled next-day load shift for illustration · no equipment changes are made</p></div><a class="primary" href="#simulator">Explore Renewable Simulator →</a></div><p class="monitoring-chart-explain">The green line moves a small assumed amount of energy from the forecast’s busiest hour to its quietest hour.</p>${optimizationChart}<div class="legend"><span><i style="background:#ed6a0b"></i>Forecast before shift</span><span><i style="background:#5b9f50"></i>Illustrative shifted forecast</span></div><div class="monitoring-scenario-stats"><div><span>Peak before</span><strong>${unit(peakBefore,'kW',1)}</strong></div><div><span>Peak after shift</span><strong>${unit(peakAfter,'kW',1)}</strong></div><div><span>Peak change</span><strong>${unit(peakBefore-peakAfter,'kW',1)}</strong></div><div><span>Energy moved</span><strong>${unit(energyMoved,'kWh',1)}</strong></div></div><p class="note monitoring-model-note">This scenario assumes flexible equipment is available. The model preserves total energy, so it does not claim energy or bill savings. No load flexibility or physical controls have been verified.</p></section>
  <details class="card monitoring-actions"><summary>View proposed efficiency actions <span>${d.actions.filter(a=>a.status==='proposed').length} available</span></summary><div class="monitoring-action-list">${d.actions.map(a=>`<article class="monitoring-action"><div><h3>${esc(a.title)}</h3><p>${esc(a.reason)}</p><small>${esc(a.detail)}</small></div><span class="badge">${esc(a.status)}</span></article>`).join('')}</div><p class="note">These are planning proposals. Review or approve them in Action recommendations on Overview.</p></details>`
}
async function openCarbonSimulator(suggestion){
  if(suggestion.assetId!==state.assetId)return;
  const assetId=state.assetId;
  state.scenarioDraft={...state.data.config};
  Object.assign(simulatorDesign(state),suggestion.design);
  state.scenarioName=suggestion.name;state.scenarioTech='pv';state.preview=null;state.previewError=null;
  Object.assign(simulatorUI,{tab:'pv',mode:'3d',after:true,case:'expected',saved:null,editing:null,compare:[]});
  installationView=null;state.calculating=true;
  const payload=scenarioPayload(state);
  location.hash='simulator';
  try{const result=await post('/preview',payload);if(state.assetId===assetId)state.preview=result;}
  catch(error){if(state.assetId===assetId)state.previewError=error.message;}
  finally{if(state.assetId===assetId){state.calculating=false;render();}}
}
function simulator(){return simulatorPage(state,{heading,chart});}
function carbon(){return carbonPage(state,{filters});}
function approvedAlertImpact(){
  const d=state.data,m=d.metrics,settled=(d.alerts||[]).filter(a=>a.status==='settled');
  if(!settled.length)return '';
  return `<section class="card card-pad alert-plan-impact" aria-label="Approved alert impact"><div class="card-head"><h2>Approved impact</h2><span class="badge">${settled.length} settled</span></div><p class="note">Next 24 hours · projected approved plan</p><div class="impact-grid"><div><span>Cost savings</span><strong>${money(m.projected_cost_difference_myr)}</strong></div><div><span>Energy saved</span><strong>${unit(m.projected_energy_reduction_kwh,'kWh',1)}</strong></div><div><span>Carbon avoided</span><strong>${unit(m.projected_avoided_carbon_kg,'kg CO₂e',1)}</strong></div></div></section>`;
}
function townshipAlertPanel(){
  const items=state.township?.items||[];
  const all=items.flatMap(item=>(item.alerts||[]).map(alert=>({...alert,asset_id:item.asset.id,building_name:item.asset.name,facility_id:item.asset.facility_id})));
  const pending=all.filter(alert=>alert.status==='proposed'),settled=all.filter(alert=>alert.status==='settled');
  const critical=alert=>floorZones(alert.facility_id,alert.floor).find(zone=>zone.id===alert.zone)?.status==='Critical';
  const ordered=[...pending].sort((a,b)=>Number(critical(b))-Number(critical(a))||a.building_name.localeCompare(b.building_name)||a.floor_label.localeCompare(b.floor_label));
  const warning='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M10.3 4.2 2.6 17.5A2 2 0 0 0 4.3 20h15.4a2 2 0 0 0 1.7-2.5L13.7 4.2a2 2 0 0 0-3.4 0Z"/><path d="M12 9v5m0 2v1"/></svg>';
  return `<section class="card card-pad recommendations alert-recommendations" aria-label="Township manager alerts"><div class="card-head"><div><h2>Action recommendations</h2><p class="manager-alert-intro">Township manager alerts · review and approve a solution for each issue.</p></div><span class="badge">${pending.length} open alert${pending.length===1?'':'s'}</span></div><div class="manager-alert-list">${ordered.length?ordered.map((alert,index)=>{const urgent=critical(alert);return `<article class="rec manager-alert ${urgent?'is-critical':'is-attention'}"><div class="manager-alert-top"><span class="manager-alert-severity">${warning}${urgent?'Critical':'Needs attention'}</span><span class="manager-alert-number">Alert ${String(index+1).padStart(2,'0')}</span></div><h3>${esc(alert.title)}</h3><p class="manager-alert-building">${esc(alert.building_name)}</p><p class="alert-location"><span>${esc(alert.floor_label)}</span>${esc(alert.name)}</p><div class="manager-alert-solution"><strong>Suggested solution</strong><p>${esc(alert.solution)}</p></div><div class="alert-approve-row"><button type="button" class="ghost" data-alert-asset="${esc(alert.asset_id)}" data-alert-floor="${esc(alert.floor)}" data-alert-zone="${esc(alert.zone)}">View floor →</button><button type="button" class="primary" data-alert-asset="${esc(alert.asset_id)}" data-approve-alert="${esc(alert.id)}">Human approval</button></div></article>`}).join(''):'<p class="alerts-clear" role="status">✓ All clear. No outstanding alerts.</p>'}</div>${settled.length?`<details class="settled-alerts"><summary>${settled.length} settled alert${settled.length===1?'':'s'}</summary>${settled.map(alert=>`<p>✓ ${esc(alert.building_name)} · ${esc(alert.floor_label)} · ${esc(alert.name)} — ${esc(alert.title)}</p>`).join('')}</details>`:''}</section>`;
}
function alertRecommendationPanel(){
  const all=state.data.alerts||[],pending=all.filter(a=>a.status==='proposed'),settled=all.filter(a=>a.status==='settled');
  const conditions=a=>floorZones(state.data.asset.facility_id,a.floor).find(z=>z.id===a.zone);
  const critical=a=>conditions(a)?.status==='Critical';
  const ordered=[...pending].sort((a,b)=>Number(critical(b))-Number(critical(a)));
  const warning='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M10.3 4.2 2.6 17.5A2 2 0 0 0 4.3 20h15.4a2 2 0 0 0 1.7-2.5L13.7 4.2a2 2 0 0 0-3.4 0Z"/><path d="M12 9v5m0 2v1"/></svg>';
  return `<section class="card card-pad recommendations alert-recommendations" aria-label="Township manager alerts"><div class="card-head"><div><h2>Action recommendations</h2><p class="manager-alert-intro">Township manager alerts · review and approve a solution for each issue.</p></div><span class="badge">${pending.length} open alert${pending.length===1?'':'s'}</span></div><div class="manager-alert-list">${ordered.length?ordered.map((a,i)=>{const urgent=critical(a);return `<article class="rec manager-alert ${urgent?'is-critical':'is-attention'}"><div class="manager-alert-top"><span class="manager-alert-severity">${warning}${urgent?'Critical':'Needs attention'}</span><span class="manager-alert-number">Alert ${String(i+1).padStart(2,'0')}</span></div><h3>${esc(a.title)}</h3><p class="manager-alert-building">${esc(sourceName(state.data.asset))}</p><p class="alert-location"><span>${esc(a.floor_label)}</span>${esc(a.name)}</p><div class="manager-alert-solution"><strong>Suggested solution</strong><p>${esc(a.solution)}</p></div><div class="alert-approve-row"><button type="button" class="ghost" data-alert-floor="${esc(a.floor)}" data-alert-zone="${esc(a.zone)}">View floor →</button><button type="button" class="primary" data-approve-alert="${esc(a.id)}">Human approval</button></div></article>`}).join(''):'<p class="alerts-clear" role="status">✓ All clear. No outstanding alerts.</p>'}</div>${settled.length?`<details class="settled-alerts"><summary>${settled.length} settled alert${settled.length===1?'':'s'}</summary>${settled.map(a=>`<p>✓ ${esc(a.floor_label)} · ${esc(a.name)} — ${esc(a.title)}</p>`).join('')}</details>`:''}</section>`;
}
async function approveBuildingAlert(id,button,assetId=state.assetId){
  const current=assetId===state.assetId&&(state.data?.alerts||[]).some(alert=>alert.id===id&&alert.status==='proposed');
  const townshipPending=(state.township?.items||[]).some(item=>item.asset.id===assetId&&(item.alerts||[]).some(alert=>alert.id===id&&alert.status==='proposed'));
  if(!current&&!townshipPending)return;
  button.disabled=true;button.textContent='Applying…';
  try{await post(`/alerts/${encodeURIComponent(id)}/approve`,{asset_id:assetId});if(state.assetId===assetId){await refresh();}else{state.township=await q(`/township?period=${state.period}`);syncAlertState(state.township.items);render();}}
  catch(error){if(button.isConnected){button.disabled=false;button.textContent='Human approval';let message=button.closest('.rec').querySelector('.alert-approval-error');if(!message){message=document.createElement('p');message.className='alert-approval-error';message.setAttribute('role','alert');button.closest('.rec').appendChild(message)}message.textContent=error.message;}}
}
function confirmBuildingAlert(id,button,assetId=state.assetId){
  const selected=(state.data?.alerts||[]).find(alert=>assetId===state.assetId&&alert.id===id&&alert.status==='proposed');
  const fromTownship=(state.township?.items||[]).find(item=>item.asset.id===assetId)?.alerts?.find(alert=>alert.id===id&&alert.status==='proposed');
  const alert=selected||fromTownship;
  if(!alert)return;
  const buildingName=state.assets.find(asset=>asset.id===assetId)?.name||state.data?.asset?.name||'Building';
  dialog.innerHTML=`<h2 id="dialog-title">Approve ${esc(alert.title)}?</h2><p>${esc(buildingName)} · ${esc(alert.floor_label)} · ${esc(alert.name)}</p><p>Projected savings over the next 24 hours:</p><dl class="approval-savings"><div><dt>Money saved</dt><dd>${money(alert.cost_myr)}</dd></div><div><dt>Energy saved</dt><dd>${unit(alert.energy_kwh,'kWh',1)}</dd></div><div><dt>Carbon emissions reduced</dt><dd>${unit(alert.carbon_kg,'kg CO₂e',1)}</dd></div></dl><div class="dialog-actions"><button type="button" class="ghost" id="dialog-cancel" autofocus>Cancel</button><button type="button" class="primary" id="dialog-confirm">Confirm approval</button></div>`;
  dialog.showModal();
  document.getElementById('dialog-cancel').onclick=()=>dialog.close();
  document.getElementById('dialog-confirm').onclick=async()=>{dialog.close();await approveBuildingAlert(id,button,assetId)};
}
function recommendationPanel(){if(state.data.asset.facility_id)return alertRecommendationPanel();const d=state.data;return `<section class="card card-pad recommendations"><div class="card-head"><div><h2>✧ Action recommendations</h2><p class="note muted" style="margin-top:5px">Grid-import impact first; peak-only proposals follow.</p></div><span class="badge">${d.actions.filter(a=>a.status==='proposed').length} proposed</span></div>${d.actions.map(a=>`<div class="rec"><div class="card-head" style="margin-bottom:5px"><h3>${esc(a.title)}</h3><span class="badge">${esc(a.status)}</span></div><p>${esc(a.reason)}</p><strong class="impact-number">${unit(a.metric,a.unit,1)}</strong><details class="details"><summary>Why this action?</summary><p>${esc(a.detail)}</p></details>${a.status==='proposed'?`<div class="form-actions">${actionButton(`approve:${a.id}`,'Approve','primary',a.metric<=0?'disabled title="No positive projected impact"':'')}${actionButton(`dismiss:${a.id}`,'Dismiss','ghost')}</div>`:''}</div>`).join('')}</section>`}
function chatMessages(){return state.chat.length?state.chat.map(message=>`<div class="bubble ${message.role==='user'?'user':''}">${esc(message.text)}${message.citations?.length?`<small class="copilot-citations">Sources: ${esc(message.citations.join(' · '))}</small>`:''}</div>`).join(''):`<div class="bubble">${state.geminiStatus==='available'?'I’m NEXORA Copilot, powered by Gemini. Ask about this building’s energy, forecast, estimates or illustrative alerts. I can’t control equipment.':'Gemini is not configured on the backend, so I can’t answer questions right now.'}</div>`}
function chatForm(compact=false){return `<form class="chat-input" id="${compact?'float':'page'}-chat-form"><input name="question" autocomplete="off" placeholder="Ask about this building…" aria-label="Ask NEXORA Copilot" required ${state.chatBusy?'disabled':''}><button class="primary" type="submit" ${state.chatBusy?'disabled':''}>Send</button></form><p class="copilot-disclosure">Read-only Gemini. Your question and selected building summary are sent to Google when you send. Do not include secrets or personal information.</p>`}
function copilot(){const d=state.data,m=d.metrics;return `${heading('NEXORA Copilot','Gemini-powered answers about the selected building’s energy results.')}${sourceStrip()}<div class="chat-page"><section class="card chat-card"><div class="chat-body" id="page-chat-body">${chatMessages()}</div><div style="padding:0 12px"><div class="prompt-row">${['What is the forecast?','Summarize the open alerts','What is the carbon estimate?'].map(t=>`<button data-prompt="${esc(t)}">${t}</button>`).join('')}</div></div>${chatForm()}</section><section class="card card-pad"><div class="card-head"><h2>Current context</h2><span class="badge">${state.geminiStatus==='available'?'Gemini connected':'Gemini unavailable'}</span></div><div class="stat-row"><span>Building</span><strong>${esc(sourceName(d.asset))}</strong></div><div class="stat-row"><span>Selected history</span><strong>${state.period==='day'?'24 hours':'7 days'}</strong></div><div class="stat-row"><span>Observed</span><strong>${unit(m.observed_energy_kwh,'kWh',1)}</strong></div><div class="stat-row"><span>Next forecast</span><strong>${unit(m.forecast_energy_kwh,'kWh',1)}</strong></div><div class="stat-row"><span>Approved actions</span><strong>${d.actions.filter(a=>a.status==='approved').length}</strong></div>${details()}</section></div>`}
const views={overview,monitoring,simulator,carbon,copilot};
function render(){const view=previewInstance?.getView?.();if(view?.facility&&view.facility===state.spatialFacility){if(state.page==='simulator')installationView=view;else buildingView=view;}previewInstance?.dispose();previewInstance=null;state.page=route();const panel=state.chatOpen&&state.page!=='copilot'?`<aside class="chat-panel" aria-label="NEXORA Copilot"><div class="chat-head"><span>✦ NEXORA Copilot <small>· ${state.geminiStatus==='available'?'Gemini':'AI unavailable'}</small></span><button data-action="close-chat" class="ghost" style="min-height:23px;padding:0 6px">×</button></div><div class="chat-body" id="float-chat-body">${chatMessages()}</div>${chatForm(true)}</aside>`:'';
  const content=state.loading?'<div class="loading"><div><div class="spinner"></div>Loading building results…</div></div>':state.error?`<div class="error">${esc(state.error)} <button data-action="retry" class="ghost" style="margin-left:10px">Retry</button></div>`:state.data?views[state.page]():`<div class="empty">No building data available.</div>`;
  app.innerHTML=`<div class="shell">${header()}<main class="page">${content}</main>${panel}${state.page!=='copilot'?`<button class="copilot-fab" data-action="toggle-chat" aria-label="Open NEXORA Copilot">✦</button>`:''}</div>`;
  const simulatorForm=document.getElementById('scenario-form');if(simulatorForm&&state.page==='simulator'){syncSimulatorForm(simulatorForm,state);state.scenarioDraft=configFromForm(simulatorForm,state.scenarioDraft||state.data.config)}
  const enterFacility=openFacility;
  const townshipCanvas=document.querySelector('.township-canvas');if(townshipCanvas){const returning=townshipReturn;townshipReturn=null;previewInstance=mountSpatialTwin(townshipCanvas,{night:state.spatialNight,onEnter:enterFacility,returnFrom:returning?.facility,returnView:returning?.view});if(!previewInstance)document.querySelector('.township-fallback').hidden=false;}
  const canvas=document.querySelector('.building-canvas');if(canvas){const onSelect=floor=>selectFloor(floor);previewInstance=state.spatialFacility?mountSpatialTwin(canvas,{facility:state.spatialFacility,selectedFloor:state.floor,onFloor:onSelect,initialView:buildingView,onRoom:selectFloorRoom}):mountBuildingPreview(canvas,{floor:state.floor,tall:canvas.dataset.tall==='true',onSelect});if(previewInstance)canvas.classList.add('ready');}
  const installCanvas=document.querySelector('.sim-installation-canvas');if(installCanvas)previewInstance=mountInstallation(installCanvas,installation(state),installationView);
  if(state.page==='simulator')bindSimulator({state,render,post,dialog,getViewer:()=>previewInstance});
  if(state.page==='carbon')bindCarbonDashboard({state,render,post,refresh,dialog,openSimulator:openCarbonSimulator});
  document.querySelectorAll('.chat-body').forEach(el=>el.scrollTop=el.scrollHeight);
}
function configFromForm(form,base){const next={...base};for(const field of form.elements){if(!field.name||field.disabled||field.name==='scenario_name')continue;next[field.name]=field.name==='assumption_reference'?field.value.trim():field.value===''?null:Number(field.value)}return next}
function confirmAction(action){const title=action==='solar'?'Use solar and storage':action==='shift'?'Move flexible load':'Review efficiency target';dialog.innerHTML=`<h2 id="dialog-title">Approve ${esc(title)}?</h2><p>This updates the local approved plan and recalculates projected results. No physical equipment command will be sent.</p><div class="dialog-actions"><button class="ghost" id="dialog-cancel">Cancel</button><button class="primary" id="dialog-confirm">Approve action</button></div>`;dialog.showModal();document.getElementById('dialog-cancel').onclick=()=>dialog.close();document.getElementById('dialog-confirm').onclick=async()=>{dialog.close();await decide(action,'approve')}}
async function decide(action,decision){try{state.loading=true;render();await post(`/actions/${action}/${decision}`,{asset_id:state.assetId});await refresh()}catch(error){state.loading=false;state.error=error.message;render()}}
async function sendChat(form){const question=new FormData(form).get('question')?.trim();if(!question||state.chatBusy)return;state.chat.push({role:'user',text:question});state.chatBusy=true;render();try{const answer=await post('/copilot/gemini',{asset_id:state.assetId,period:state.period,question});state.geminiStatus='available';state.chat.push({role:'assistant',text:answer.answer,citations:(answer.citations||[]).map(source=>source.label)})}catch(error){state.chat.push({role:'assistant',text:`NEXORA Copilot couldn't answer: ${error.message}`})}finally{state.chatBusy=false;render()}}
function returnToTownship(){if(!state.spatialFacility)return;townshipReturn={facility:state.spatialFacility,view:townshipView};state.spatialFacility=null;render();window.scrollTo({top:0,behavior:'instant'})}
document.addEventListener('click',async event=>{
  const approveAlert=event.target.closest('[data-approve-alert]');if(approveAlert){confirmBuildingAlert(approveAlert.dataset.approveAlert,approveAlert,approveAlert.dataset.alertAsset||state.assetId);return}
  const alertFloor=event.target.closest('[data-alert-floor]');if(alertFloor){const assetId=alertFloor.dataset.alertAsset;if(assetId){const asset=state.assets.find(item=>item.id===assetId);if(asset){await openFacility(asset.facility_id);selectFloor(alertFloor.dataset.alertFloor);selectFloorRoom(alertFloor.dataset.alertZone);}}else{selectFloor(alertFloor.dataset.alertFloor);selectFloorRoom(alertFloor.dataset.alertZone);}return}
  const zone=event.target.closest('[data-floor-zone]');if(zone){selectFloorRoom(zone.dataset.floorZone);return}
  const energyLayer=event.target.closest('[data-energy-layer]');if(energyLayer){const id=energyLayer.dataset.energyLayer;if(!ENERGY_LAYERS.some(([key])=>key===id))return;state.energyLayer=id;document.querySelectorAll('[data-energy-layer]').forEach(button=>{const active=button.dataset.energyLayer===id;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))});document.querySelectorAll('.energy-layer-info').forEach(panel=>panel.innerHTML=energyLayerInfo());return}
  const facility=event.target.closest('[data-facility]');if(facility){if(previewInstance?.enter)previewInstance.enter(facility.dataset.facility);else openFacility(facility.dataset.facility);return}
  const camera=event.target.closest('[data-camera]');if(camera){const command=camera.dataset.camera;if(command==='in')previewInstance?.zoom(.85);if(command==='out')previewInstance?.zoom(1.15);if(command==='reset')previewInstance?.reset();if(command==='rotate')previewInstance?.rotate();return}
  const metric=event.target.closest('[data-chart-metric]');if(metric){state.chartMetric=metric.dataset.chartMetric;render();return}
  const simTab=event.target.closest('[data-sim-tab]');if(simTab){simulatorUI.tab=simTab.dataset.simTab;render();return}
  const simToggle=event.target.closest('[data-sim-toggle]');if(simToggle){const form=document.getElementById('scenario-form');if(form){syncSimulatorForm(form,state);state.scenarioDraft=configFromForm(form,state.scenarioDraft||state.data.config)}const solar=!!document.querySelector('[data-sim-toggle="pv"]')?.checked,battery=!!document.querySelector('[data-sim-toggle="battery"]')?.checked;state.scenarioTech=solar&&battery?'pv_battery':solar?'pv':'battery';simulatorUI.tab=solar?'pv':'battery';state.preview=null;render();return}
  const simMode=event.target.closest('[data-sim-mode]');if(simMode){simulatorUI.mode=simMode.dataset.simMode;render();return}
  const simView=event.target.closest('[data-sim-view]');if(simView){simulatorUI.after=simView.dataset.simView==='after';render();return}
  const simCase=event.target.closest('[data-sim-case]');if(simCase){simulatorUI.case=simCase.dataset.simCase;render();return}
  const simLoad=event.target.closest('[data-sim-load]');if(simLoad){const saved=state.data.scenarios.find(s=>s.id===simLoad.dataset.simLoad);if(saved){state.scenarioTech=saved.technology;state.scenarioDraft={...saved.config};state.scenarioName=saved.name;simulatorUI.tab=state.scenarioTech==='battery'?'battery':'pv';state.preview=null;render()}return}
  const simCopy=event.target.closest('[data-sim-copy]');if(simCopy){const saved=state.data.scenarios.find(s=>s.id===simCopy.dataset.simCopy);if(saved){try{await post('/scenarios',{asset_id:state.assetId,name:`${saved.name} copy`,technology:saved.technology,config:saved.config});await refresh()}catch(error){state.error=error.message;render()}}return}
  const simBrief=event.target.closest('[data-sim-brief]');if(simBrief){const payload={building:state.data.asset.name,technology:state.scenarioTech,configuration:state.scenarioDraft,impact:{grid_avoided_kwh:state.preview?.grid_avoided_kwh,cost_difference_myr:state.preview?.cost_difference_myr,peak_reduction_kw:state.preview?.peak_reduction_kw},note:'Planning estimate from the selected forecast; verify site conditions and equipment before procurement.'};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='renewable-installation-brief.json';link.click();URL.revokeObjectURL(url);return}
  const floor=event.target.closest('[data-floor]');if(floor){selectFloor(floor.dataset.floor);return}
  const room=event.target.closest('[data-room]');if(room){state.room=room.dataset.room;render();return}
  const tech=event.target.closest('[data-tech]');if(tech){const form=document.getElementById('scenario-form');if(form){state.scenarioDraft=configFromForm(form,state.scenarioDraft||state.data.config);state.scenarioName=form.elements.scenario_name.value}state.scenarioTech=tech.dataset.tech;state.preview=null;render();return}
  const prompt=event.target.closest('[data-prompt]');if(prompt){const form=document.getElementById('page-chat-form')||document.getElementById('float-chat-form');if(form){form.elements.question.value=prompt.dataset.prompt;sendChat(form)}return}
  const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;
  if(action==='township-back'){returnToTownship();return}
  if(action==='township-night'){state.spatialNight=!state.spatialNight;render();return}
  if(action==='toggle-menu'){state.menuOpen=!state.menuOpen;render();return}
  if(action==='toggle-chat'){state.chatOpen=!state.chatOpen;render();return}if(action==='close-chat'){state.chatOpen=false;render();return}if(action==='retry'){refresh();return}
  if(action.startsWith('approve:')){confirmAction(action.split(':')[1]);return}if(action.startsWith('dismiss:')){await decide(action.split(':')[1],'dismiss');return}
  if(action==='save-scenario'&&state.preview){const form=document.getElementById('scenario-form');const name=form?.elements.scenario_name?.value?.trim()||'Scenario';try{button.disabled=true;await post('/scenarios',{asset_id:state.assetId,name,technology:state.scenarioTech,config:state.scenarioDraft});state.preview=null;await refresh()}catch(error){state.previewError=error.message;render()}return}
});
document.addEventListener('change',event=>{if(event.target.matches('[data-sim-compare]')){const id=event.target.dataset.simCompare;simulatorUI.compare=event.target.checked?[...simulatorUI.compare,id].slice(-3):simulatorUI.compare.filter(x=>x!==id);render();return}if(event.target.id==='building-select')selectAsset(event.target.value);if(event.target.id==='period-select'){state.period=event.target.value;rememberView();refresh()}});
document.addEventListener('input',event=>{const form=event.target.closest('#scenario-form');if(!form)return;syncSimulatorForm(form,state);state.scenarioDraft=configFromForm(form,state.scenarioDraft||state.data.config);state.scenarioName=form.elements.scenario_name.value;previewInstance?.setInstallation?.(installation(state));if(event.target.name!=='scenario_name'){state.preview=null;const save=document.querySelector('[data-action="save-scenario"]');if(save){save.disabled=true;save.textContent='Inputs changed · recalculate'}}});
document.addEventListener('submit',async event=>{
  const form=event.target;if(!['scenario-form','config-form','page-chat-form','float-chat-form'].includes(form.id))return;event.preventDefault();
  if(form.id.endsWith('chat-form')){await sendChat(form);return}
  if(form.id==='config-form'){try{const config=configFromForm(form,state.data.config);state.loading=true;render();await post('/configuration',{asset_id:state.assetId,config});await refresh()}catch(error){state.loading=false;state.error=error.message;render()}return}
  if(state.calculating)return;syncSimulatorForm(form,state);state.scenarioDraft=configFromForm(form,state.scenarioDraft||state.data.config);const name=form.elements.scenario_name.value.trim();state.scenarioName=name;const submit=form.querySelector('[type=submit]');state.calculating=true;submit.disabled=true;submit.textContent='Calculating…';try{state.previewError=null;state.preview=await post('/preview',{asset_id:state.assetId,name,technology:state.scenarioTech,config:state.scenarioDraft});}catch(error){state.preview=null;state.previewError=error.message;}finally{state.calculating=false;render()}
});
window.addEventListener('hashchange',()=>{state.page=route();state.menuOpen=false;render();window.scrollTo({top:0,behavior:'instant'})});
window.matchMedia('(max-width:540px)').addEventListener('change',()=>{if(state.page==='carbon'&&!state.loading)render();});
init();
